for(const locale of SUPPORTED_LOCALES)Object.assign(DICTS[locale],UI_POLISH[locale]||{});

export const LOCALE_OPTIONS=[
  {value:'en-US',flagSrc:'/assets/flags/en-US.svg',label:'English'},
  {value:'zh-CN',flagSrc:'/assets/flags/zh-CN.svg',label:'简体中文'},
  {value:'ru-RU',flagSrc:'/assets/flags/ru-RU.svg',label:'Русский'},
  {value:'es-419',flagSrc:'/assets/flags/es-419.svg',label:'Español (Latinoamérica)'},
];
export function localeFlag(locale=getLocale()){return LOCALE_OPTIONS.find(x=>x.value===normalizedLocale(locale))?.flagSrc||'/assets/flags/en-US.svg'}
let POI_LOCALIZATION_META=null;
export async function loadPoiLocalizationMeta(url='/data/place_names_meta.json'){
  try{const r=await fetch(url,{cache:'no-store'});if(r.ok){const j=await r.json();POI_LOCALIZATION_META=j&&typeof j==='object'?j:null}}catch{}
  return POI_LOCALIZATION_META;
}
export function poiLocalizationStatus(meta=POI_LOCALIZATION_META,locale=getLocale()){
  const loc=normalizedLocale(locale);
  if(!meta||meta.status!=='ready')return translateForLocale(loc,'drive.poiLocalizationFallback');
  const row=meta.coverage?.[loc]||{};
  const matched=Number(row.matched||0),total=Number(row.total||meta.total_game_places||0);
  return translateForLocale(loc,'drive.poiLocalizationReady',{matched,total});
}
export function normalizedLocale(value){
  const raw=String(value||'').replace('_','-').toLowerCase();
  if(raw.startsWith('zh'))return 'zh-CN';
  if(raw.startsWith('ru'))return 'ru-RU';
  if(raw.startsWith('es'))return 'es-419';
  return 'en-US';
}
export function getLocale(){
  let query='';try{const params=new URLSearchParams(location.search);query=params.get('lang')||''}catch{}
  if(query){const locale=normalizedLocale(query);try{localStorage.setItem(LOCALE_STORAGE,locale)}catch{}return locale}
  let saved='';try{saved=localStorage.getItem(LOCALE_STORAGE)||''}catch{}
  return saved?normalizedLocale(saved):normalizedLocale(navigator?.language||'en-US');
}
export function hasTranslation(locale,key){return Object.prototype.hasOwnProperty.call(DICTS[normalizedLocale(locale)]||{},key)}
export function translateForLocale(locale,key,vars={}){
  const loc=normalizedLocale(locale),value=(DICTS[loc]?.[key]??EN[key]??key);
  return String(value).replace(/\{(\w+)\}/g,(_,name)=>vars[name]??`{${name}}`);
}
export function t(key,vars={}){return translateForLocale(getLocale(),key,vars)}
export function applyTranslations(root=document,locale=getLocale()){
  document.documentElement.lang=locale;
  root.querySelectorAll?.('[data-i18n]').forEach(el=>{el.textContent=translateForLocale(locale,el.dataset.i18n)});
  root.querySelectorAll?.('[data-i18n-placeholder]').forEach(el=>{el.placeholder=translateForLocale(locale,el.dataset.i18nPlaceholder)});
  root.querySelectorAll?.('[data-i18n-title]').forEach(el=>{el.title=translateForLocale(locale,el.dataset.i18nTitle)});
  root.querySelectorAll?.('[data-i18n-aria-label]').forEach(el=>{el.setAttribute('aria-label',translateForLocale(locale,el.dataset.i18nAriaLabel))});
  return locale;
}
export function setLocale(locale){
  const next=normalizedLocale(locale);try{localStorage.setItem(LOCALE_STORAGE,next)}catch{}
  applyTranslations(document,next);
  window.dispatchEvent(new CustomEvent('fh6:localechange',{detail:{locale:next}}));return next;
}
export function populateLocaleSelect(select){
  if(!select)return;select.replaceChildren();
  for(const {value,label} of LOCALE_OPTIONS){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
  select.value=getLocale();
}
export function bindLocaleSelect(select){if(!select)return;populateLocaleSelect(select);select.addEventListener('change',()=>setLocale(select.value));}
export function bindLocaleFlagMenu(button,menu){
  if(!button||!menu)return;
  const items=[...menu.querySelectorAll('[data-locale-value]')],status=menu.querySelector('#localePoiStatus');
  let meta=POI_LOCALIZATION_META;
  const refresh=()=>{
    const current=getLocale(),opt=LOCALE_OPTIONS.find(x=>x.value===current)||LOCALE_OPTIONS[0];
    let image=button.querySelector('.locale-flag-image');
    if(!image){image=document.createElement('img');image.className='locale-flag-image';image.alt='';button.replaceChildren(image)}
    image.src=opt.flagSrc;button.setAttribute('aria-label',t('drive.languageTooltip'));button.setAttribute('aria-expanded',menu.hidden?'false':'true');
    for(const item of items){const active=item.dataset.localeValue===current;item.classList.toggle('active',active);item.setAttribute('aria-checked',active?'true':'false')}
    if(status)status.textContent=poiLocalizationStatus(meta,current);
  };
  const close=()=>{menu.hidden=true;button.setAttribute('aria-expanded','false')};
  button.addEventListener('click',e=>{e.stopPropagation();menu.hidden=!menu.hidden;refresh()});
  for(const item of items)item.addEventListener('click',e=>{e.stopPropagation();setLocale(item.dataset.localeValue);close();refresh()});
  document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!button.contains(e.target))close()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
  window.addEventListener('fh6:localechange',refresh);refresh();
  loadPoiLocalizationMeta().then(value=>{meta=value;refresh()});
}
